mapper.select:
    SELECT * FROM (

            /*流程中*/
            SELECT * FROM (
            SELECT
            /* 有效状态 */ '${PAGE_DATE_STATUS03}' statusValid,
            /* 业务编号 */ T1.TOTLE_TRADE_ID busiCode,
            /* 类型 */ T1.PS CASH_TYPE,
            T4.TYPE_6,
            T3.FINPROD_ID,
            T3.CCY, t1.CHL_ID chlId, NVL(T5.FINPROD_ABBR, T5.FINPROD_NAME) chlName,
            /* 资产代码 */ T3.FINPROD_MARKET_ID,
            /* 资产名称 */ T3.FINPROD_NAME finprodMarketName,
            /* 剩余本金 */ T2.REMAIN_PRIN_AMT qty,
            /* 还本金额 */ T2.THEORY_PRIN returnAmount,
            /* 借款利率 */ T2.RATE*100 yield,
            /* 计息开始日 */ to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
            /* 计息结束日 */ to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
            /* 资金到账日 */ to_char(T1.TRADE_DATE, 'yyyy-MM-dd') arrivalDate,
            /* 支付日 */ to_char(T2.THEORY_PAY_DATE, 'yyyy-MM-dd') interestPayDay,
            /* 理论本息总额 */ T2.THEORY_AMT,
            /* 实收本息总额 */ T1.FPRICE_AMT,

            T1.TRADE_AMT arrivalAmt,

            t1.WORKFLOW_ID,t2.PA_BUSS_TYPE
            FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1
            LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
            LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID
            LEFT JOIN FIN_PRODUCT_TYPE T4 ON T1.FINPROD_ID = T4.FINPROD_ID
            LEFT JOIN FIN_PRODUCT T5 ON T1.CHL_ID = T5.FINPROD_ID
            WHERE
            T1.TRADE_STATUS = #{TRADE_STATUS01}
            AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/
            AND T1.IS_CANCEL = #{YESNO_N}
            AND T1.BUSI_TYPE = #{TRD15}
            AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17}
            AND T1.PORTFOLIO_ID IS NULL
            AND EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
            where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND DEAL.PORTFOLIO_ID )

                AND (instr(T1.TOTLE_TRADE_ID, #{busiCode}) > 0)


                AND T3.FINPROD_MARKET_ID = #{finprodMarketId}


                AND T2.PA_BUSS_TYPE = #{paBizType}


                AND T4.TYPE_6 = #{projectType}


                AND T1.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')


                AND T1.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')


                AND T1.TRADE_DATE >= to_date(#{arrivalDateStart}, 'yyyy-MM-dd')


                AND T1.TRADE_DATE <= to_date(#{arrivalDateEnd}, 'yyyy-MM-dd')

            ORDER BY T1.TRADE_DATE DESC
            )


            /*待处理*/

                UNION ALL

            SELECT * FROM (
                select
                  /* 有效状态 */ '${PAGE_DATE_STATUS01}'           statusValid,
                  /* 业务编号 */ null                              busiCode,
                  /* 类型 */    t8.CASH_TYPE, T4.TYPE_6, T10.FINPROD_ID, T10.CCY,
                       CASE WHEN T8.SEC_ACCT_ID = '999999' THEN NULL ELSE
                       t8.SEC_ACCT_ID END chlId,
                       NVL(T5.FINPROD_ABBR, T5.FINPROD_NAME) chlName,
                  /* 资产代码 */ T10.FINPROD_MARKET_ID,
                  /* 资产名称 */ T10.FINPROD_NAME                  finprodMarketName,
                  /* 剩余本金 */ 

                    ROUND(SUM(T8.QTY), 4) qty,

                  /* 还本金额 */ ROUND(SUM(nvl(T8.prinAmt, 0)), 4) returnAmount,
                  /* 借款利率 */ fccr.YIELD*100 YIELD,
                  /* 计息开始日 */ to_char(t8.VDATE, 'yyyy-MM-dd')  vDate,
                  /* 计息结束日 */ to_char(t8.MDATE, 'yyyy-MM-dd')  mDate,
                  /* 资金到账日 */ null                             arrivalDate,
                  /* 支付日 */ to_char(t8.PAY_DATE, 'yyyy-MM-dd') interestPayDay,
                  /* 理论本息总额 */ ROUND(SUM(T8.fpriceAmt), 4)                    THEORY_AMT,
                  /* 实收本息总额 */ null                            FPRICE_AMT,

		          null arrivalAmt,

                  null WORKFLOW_ID,
                  null PA_BUSS_TYPE
                   from (select T7.FINPROD_ID,
                        T7.AMOUNT QTY,SUM(decode(T7.dqprinamt, null, t7.int_prin_amt * T7.AMOUNT/T7.MAX_CASH_BASEAMT, null)) return_amt,

                        T7.PORTFOLIO_ID,
                        T7.SEC_ACCT_ID,

                        listagg(T7.CASH_TYPE, ',')  within group ( order by T7.CASH_ID ) CASH_TYPE,
                        listagg(T7.CASH_ID, ',')  within group ( order by T7.CASH_ID ) CASH_ID,
                        min(T7.VDATE) VDATE,
                        T7.MDATE,
                        SUM(cast(T7.CASH_AMT as DECIMAL(30,8)) * T7.AMOUNT/T7.CASH_BASEAMT)            fpriceAmt,
                        max(T7.INT_PRIN_AMT) INT_PRIN_AMT,
                        /*理论本息总额*/
                        SUM(cast(T7.PRIN_AMT as DECIMAL(30,8)) * T7.AMOUNT/T7.CASH_BASEAMT) prinAmt,
                        /*还本金额*/
                        SUM(T7.INT_AMT * T7.AMOUNT/T7.CASH_BASEAMT) intAmt,
                        /*T7.payedInt,
                        T7.payedPrinAmt,*/
                        /*理论利息*/
                        T7.PAY_DATE
                 from (
                        SELECT
                            t6.FINPROD_ID,

                            t6.PORTFOLIO_ID,

                            t6.AMOUNT,
                            /*这一层，同一组合持仓对不用计划，数量不合并*/
                            T6.SEC_ACCT_ID,
                            T6.CASH_TYPE,
                            T6.CASH_ID,
                            T6.VDATE,
                            T6.MDATE,
                            T6.CASH_AMT,
                            t6.INT_PRIN_AMT,
                            T6.PRIN_AMT,
                            case when t6.cash_type in ('04', '01') then 0 else t6.prin_amt end dqprinamt,
                            T6.CASH_BASEAMT,
                            /*还本金额*/
                            t6.INT_AMT,
                            /*理论利息*/
                            t6.PAY_DATE,
                            MAX(FCP11.CASH_BASEAMT) MAX_CASH_BASEAMT
                       from (
                            select * from (
                                SELECT
                                    T1.FINPROD_ID,
                                    T1.AMOUNT,
                                    T1.SEC_ACCT_ID,
                                    T1.PORTFOLIO_ID,
                                    t2.vdate_term vdate,
                                    t2.mdate,
                                    t2.cash_amt,
                                    t2.prin_amt,
                                    t2.int_amt,
                                    t2.cash_id,
                                    t2.cash_type,
                                    t2.pay_date,
                                    t2.INT_PRIN_AMT,
                                    t2.CASH_BASEAMT,
                                    rank() over(partition BY t1.finprod_id ORDER BY t2.mdate) rank
                                FROM PTL_SEC_POSITION T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID
                                inner join PTL_PORTFOLIO pp on T1.PORTFOLIO_ID = pp.PORTFOLIO_ID
                                AND T2.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND t1.CDATE < t2.MDATE

                                    T1.AMOUNT > 0 AND T1.HODING_TYPE = #{POSITION_TYPE03}

                                        AND (instr(#{cashTypeSb}, T2.CASH_TYPE) > 0)


                                        AND t1.finprod_id=#{finprodId}


                                        and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04})

                                    and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0)

                                    /*不存在生效的交易*/
                                    and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01}
                                    AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE = TPDA.MDATE
                                    AND TPDA.FINPROD_ID = T1.FINPROD_ID
                                    AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
                                    AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))

                                    /*不存在流程中的当期或之前的交易*/
                                    AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01}
                                    AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE >= TPDA.MDATE
                                    AND TPDA.FINPROD_ID = T1.FINPROD_ID
                                    AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
                                    AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))

                                        AND T1.SEC_ACCT_ID = #{chlId}



                                    AND NOT EXISTS (
                                    SELECT 1 FROM PTL_SEC_POSITION tpsp
                                    where tpsp.HODING_TYPE = #{POSITION_TYPE03}
                                    and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID
                                    and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID
                                    and tpsp.FINPROD_ID = T1.FINPROD_ID
                                    and tpsp.CDATE > T1.CDATE
                                    and tpsp.CDATE < t2.MDATE
                                    )
                                    and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
                                    and T2.PAY_DATE >= #{PLATEFORM_DATE}

                                    and T1.PORTFOLIO_ID 

                                        #{item}

                                ) where rank = 1
                            ) T6 INNER JOIN FIN_CASH_PLAN FCP11 ON T6.FINPROD_ID = FCP11.FINPROD_ID


                                AND T6.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')


                                AND T6.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')


                        GROUP BY

                            T6.PORTFOLIO_ID,

                            T6.AMOUNT,
                            T6.FINPROD_ID,
                            T6.SEC_ACCT_ID,
                            T6.CASH_TYPE,
                            T6.CASH_ID,
                            T6.VDATE,
                            T6.MDATE,
                            T6.CASH_AMT,
                            t6.INT_PRIN_AMT,
                            T6.PRIN_AMT,
                            T6.CASH_BASEAMT,
                            t6.INT_AMT,
                            t6.PAY_DATE
                        ) T7
                        GROUP BY

                            T7.PORTFOLIO_ID,

                            T7.FINPROD_ID,T7.SEC_ACCT_ID,
                            T7.AMOUNT,
                            T7.MDATE,
                            /*T7.payedInt,*/
                            /*T7.payedPrinAmt,*/
                            T7.PAY_DATE
                    ) T8
                  LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID
                  LEFT JOIN FIN_PRODUCT_TYPE T4 ON T10.FINPROD_ID = T4.FINPROD_ID
                  LEFT JOIN FIN_CASH_CALC_RULE fccr ON instr(t8.CASH_ID, fccr.CASH_ID) > 0 AND fccr.EFF_DATE <= T8.MDATE
                  LEFT JOIN FIN_PRODUCT T5 ON T8.SEC_ACCT_ID = T5.FINPROD_ID
            WHERE NOT EXISTS(SELECT 1
                            FROM FIN_CASH_CALC_RULE T6
                            WHERE fccr.CASH_ID = T6.CASH_ID
                              AND T6.EFF_DATE <= T8.MDATE
                              AND T6.EFF_DATE > fccr.EFF_DATE
               )
             and T10.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17}

                AND T8.CASH_TYPE = #{cashType}


                AND instr(T8.CASH_TYPE, #{cashType}) > 0


                AND t10.FINPROD_MARKET_ID = #{finprodMarketId}


                AND T4.TYPE_6 = #{projectType}

            GROUP BY t8.CASH_TYPE,T4.TYPE_6, T10.FINPROD_ID, T10.CCY,
            /* 资产代码 */ T10.FINPROD_MARKET_ID,
            /* 资产名称 */ T10.FINPROD_NAME,t8.SEC_ACCT_ID,t5.FINPROD_ABBR,t5.FINPROD_NAME,
            /* 借款利率 */ fccr.YIELD,
            /* 计息开始日 */ t8.VDATE,
            /* 计息结束日 */ t8.MDATE,
                            t8.PAY_DATE
            ORDER BY T8.PAY_DATE
            )




                UNION ALL

            /*有效数据*/
            SELECT * FROM (
            SELECT
            /* 有效状态 */ '${PAGE_DATE_STATUS05}' statusValid,
            /* 业务编号 */ T1.TOTLE_TRADE_ID busiCode,
            /* 类型 */ T1.PS CASH_TYPE,T4.TYPE_6,
            T3.FINPROD_ID,
            T3.CCY,t1.CHL_ID chlId,NVL(T5.FINPROD_ABBR, T5.FINPROD_NAME) chlName,
            /* 资产代码 */ T3.FINPROD_MARKET_ID,
            /* 资产名称 */ T3.FINPROD_NAME finprodMarketName,
            /* 剩余本金 */ T2.REMAIN_PRIN_AMT qty,
            /* 还本金额 */ T2.THEORY_PRIN returnAmount,
            /* 借款利率 */ T2.RATE*100 yield,
            /* 计息开始日 */ to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
            /* 计息结束日 */ to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
            /* 资金到账日 */ to_char(T1.TRADE_DATE, 'yyyy-MM-dd') arrivalDate,
            /* 支付日 */ to_char(T2.THEORY_PAY_DATE, 'yyyy-MM-dd') interestPayDay,
            /* 理论本息总额 */ T2.THEORY_AMT,
            /* 实收本息总额 */ T1.FPRICE_AMT,

            T1.TRADE_AMT arrivalAmt,

            null WORKFLOW_ID,
            T2.PA_BUSS_TYPE
            FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
            LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
            LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID
            LEFT JOIN FIN_PRODUCT_TYPE T4 ON T1.FINPROD_ID = T4.FINPROD_ID
            LEFT JOIN FIN_PRODUCT T5 ON T1.CHL_ID = T5.FINPROD_ID
            WHERE
            T1.TRADE_STATUS = #{TRADE_STATUS01}
            AND T1.IS_CANCEL = #{YESNO_N}
            AND T1.BUSI_TYPE = #{TRD15}
            AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17}
            AND EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
            where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND DEAL.PORTFOLIO_ID )

                AND (instr(T1.TOTLE_TRADE_ID, #{busiCode}) > 0)


                AND T3.FINPROD_MARKET_ID = #{finprodMarketId}


                AND T2.PA_BUSS_TYPE = #{paBizType}


                AND T1.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')


                AND T1.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')


                AND T4.TYPE_6 = #{projectType}


                AND T1.TRADE_DATE >= to_date(#{arrivalDateStart}, 'yyyy-MM-dd')


                AND T1.TRADE_DATE <= to_date(#{arrivalDateEnd}, 'yyyy-MM-dd')

            ORDER BY T1.FINPROD_ID, T1.TRADE_DATE DESC, t1.MDATE DESC
            )


            /*撤销数据*/

                UNION ALL

            SELECT * FROM (
            SELECT
            /* 有效状态 */ '${PAGE_DATE_STATUS06}' statusValid,
            /* 业务编号 */ T1.P_TRADE_ID busiCode,
            /* 类型 */ T1.PS CASH_TYPE,
            T4.TYPE_6,
            T3.FINPROD_ID,
            T3.CCY,t1.CHL_ID chlId,NVL(T5.FINPROD_ABBR, T5.FINPROD_NAME) chlName,
            /* 资产代码 */ T3.FINPROD_MARKET_ID,
            /* 资产名称 */ T3.FINPROD_NAME finprodMarketName,
            /* 剩余本金 */ T2.REMAIN_PRIN_AMT qty,
            /* 还本金额 */ T2.THEORY_PRIN returnAmount,
            /* 借款利率 */ T2.RATE*100 yield,
            /* 计息开始日 */ to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
            /* 计息结束日 */ to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
            /* 资金到账日 */ to_char(T1.TRADE_DATE, 'yyyy-MM-dd') arrivalDate,
            /* 支付日 */ to_char(T2.THEORY_PAY_DATE, 'yyyy-MM-dd') interestPayDay,
            /* 理论本息总额 */ T2.THEORY_AMT,
            /* 实收本息总额 */ T1.FPRICE_AMT,

            T1.TRADE_AMT arrivalAmt,

            null WORKFLOW_ID,
            T2.PA_BUSS_TYPE
            FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
            LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
            LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID
            LEFT JOIN FIN_PRODUCT_TYPE T4 ON T1.FINPROD_ID = T4.FINPROD_ID
            LEFT JOIN FIN_PRODUCT T5 ON T1.CHL_ID = T5.FINPROD_ID
            WHERE
            T1.TRADE_STATUS = #{TRADE_STATUS03}
            AND T1.BUSI_TYPE = #{TRD15}
            AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17}
            AND EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
            where DEAL.P_TOTLE_TRADE_ID = T1.P_TRADE_ID AND DEAL.PORTFOLIO_ID )

                AND (instr(T1.P_TRADE_ID, #{busiCode}) > 0)


                AND T3.FINPROD_MARKET_ID = #{finprodMarketId}


                AND T2.PA_BUSS_TYPE = #{paBizType}


                AND T1.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')


                AND T1.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')


                AND T4.TYPE_6 = #{projectType}


                AND T1.TRADE_DATE >= to_date(#{arrivalDateStart}, 'yyyy-MM-dd')


                AND T1.TRADE_DATE <= to_date(#{arrivalDateEnd}, 'yyyy-MM-dd')

            ORDER BY T1.TRADE_DATE
            )

        )

        /*检索项目*/                        SELECT
        /*金融产品分类表.分类6 一级分类*/         T2.TYPE_6,
        /*金融产品分类表.分类7 二级分类*/         T2.TYPE_7,
        /*标的类金融产品.市场代码 资产代码*/       T1.FINPROD_MARKET_ID,
        /*标的类金融产品.金融产品名称 资产名称*/   T1.FINPROD_NAME,
        /*标的类金融产品.发行规模 初始投资金额*/   T1.ISSUE_AMT,
        /*传参.类型 类型*/                      '${cashType}' cashType,
        /*标的类金融产品.起息日 起息日*/          to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
        /*标的类金融产品.到期日 到期日*/          to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
        /*现金流计算规则表.计算基础 计息基础*/     t4.BASIS,
        /*标的类金融产品.币种 币种*/              t1.CCY
        /*检索对象*/                        FROM
        /*标的类金融产品*/                     FIN_PRODUCT T1
        /*left join 金融产品分类表*/           LEFT JOIN FIN_PRODUCT_TYPE T2
        /*on 标的类金融产品.金融产品代码 = 金融产品分类表.金融产品代码*/ ON T1.FINPROD_ID = T2.FINPROD_ID
        /*left join 现金流信息表*/            LEFT JOIN FIN_CASH_INFO T3
        /*on 标的类金融产品.金融产品代码 = 现金流信息表.业务代码*/ ON T1.FINPROD_ID = T3.FINPROD_ID
        /*and 现金流信息表.现金流一级类型 = 数据字典缓存.现金流一级类型.利息*/ AND T3.CASH_TYPE_1 = #{CASH_TYPE_1_02}
        /*and 现金流信息表.现金流二级类型 = 数据字典缓存.现金流二级类型.利息*/ AND T3.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
        /*left join 现金流计算规则表*/         LEFT JOIN FIN_CASH_CALC_RULE T4 ON T3.CASH_ID = T4.CASH_ID AND T4.EFF_DATE <= to_date(#{interestPayDay}, 'yyyy-MM-dd')
/*        现金流信息表.现金流代码 = 现金流计算规则表.现金流代码*/
       /*检索条件*/                      WHERE T1.FINPROD_ID = #{finprodId}
        AND NOT EXISTS (
            SELECT 1 FROM FIN_CASH_CALC_RULE T5 WHERE T4.CASH_ID = T5.CASH_ID
              AND T5.EFF_DATE <= to_date(#{interestPayDay}, 'yyyy-MM-dd')
              AND T5.EFF_DATE > T4.EFF_DATE
        )
        /*标的类金融产品.金融产品代码 = 传参.金融产品代码*/

select.if:
SELECT
'${statusValid}' statusValid,
'${finprodId}' finprodId,
'${CASH_TYPE_1_02}' CASH_TYPE_1_02,
'${CASH_TYPE_2_C02}' CASH_TYPE_2_C02,
T1.ps cashType,
T2.PA_BUSS_TYPE,
T1.CHL_ID,

    T1.TOTLE_TRADE_ID busiCode,
    null cancel_remark ,


    T1.P_TRADE_ID busiCode,
    null cancel_remark ,

/*总剩余本金*/ T2.REMAIN_PRIN_AMT qty,
/*计息开始日 */ to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
/*计息结束日 */ to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
/*利息调整 */ t1.FPRICE_AMT-t2.THEORY_PRIN-t2.THEORY_INT intAdjustment,
/*理论支付日 */ to_char(T2.THEORY_PAY_DATE, 'yyyy-MM-dd') interestPayDay,
/*还本金额 */ t2.THEORY_PRIN returnAmount,
/*理论应收利息 */ t2.THEORY_INT intAmtTheory,
/*实收本息总额 */ t1.FPRICE_AMT fpriceAmt,
/*税费金额 */ t3.FEE_AMT taxAmount,
/*到账金额 */ t1.TRADE_AMT arrivalAmt,
/*资金到账日 */ to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') arrivalDate,
t1.REMARK,
FP.COLLECT_TYPE,
CASE WHEN  T1.CHL_ID IS NULL  THEN 0 ELSE 1 END channel,
T1.FEE_AMT channelFee
FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
LEFT JOIN TRD_TRADE_FEE_DETAIL T3 ON T3.TRADE_ID = T1.TOTLE_TRADE_ID

LEFT JOIN FIN_PRODUCT_ADD FP ON T1.CHL_ID = FP.FINPROD_ID
where
 T1.PORTFOLIO_ID IS NULL

    AND T1.TOTLE_TRADE_ID = #{busiCode}


    AND T1.P_TRADE_ID = #{busiCode}

SELECT
'${statusValid}' statusValid,
'${finprodId}' finprodId,
'${CASH_TYPE_1_02}' CASH_TYPE_1_02,
'${CASH_TYPE_2_C02}' CASH_TYPE_2_C02,
T1.ps cashType,
T2.PA_BUSS_TYPE,
T1.CHL_ID,
/*业务编号*/ T1.TOTLE_TRADE_ID busiCode,
/*总剩余本金*/ T2.REMAIN_PRIN_AMT qty,
/*计息开始日 */ to_char(T1.VDATE, 'yyyy-MM-dd') vDate,
/*计息结束日 */ to_char(T1.MDATE, 'yyyy-MM-dd') mDate,
/*利息调整 */ t1.FPRICE_AMT-t2.THEORY_PRIN-t2.THEORY_INT intAdjustment,
/*理论支付日 */ to_char(T2.THEORY_PAY_DATE, 'yyyy-MM-dd') interestPayDay,
/*还本金额 */ t2.THEORY_PRIN returnAmount,
/*理论应收利息 */ t2.THEORY_INT intAmtTheory,
/*实收本息总额 */ t1.FPRICE_AMT fpriceAmt,
/*税费金额 */ t3.FEE_AMT taxAmount,
/*到账金额 */ t1.TRADE_AMT arrivalAmt,
/*资金到账日 */ to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') arrivalDate,
t1.REMARK,
 FP.COLLECT_TYPE,
 CASE WHEN T1.CHL_ID IS NULL  THEN 0 ELSE 1 END channel,
 T1.FEE_AMT channelFee
FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1
LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID
LEFT JOIN TRD_TRADE_FEE_DETAIL T3 ON T3.TRADE_ID = T1.TOTLE_TRADE_ID

LEFT JOIN FIN_PRODUCT_ADD FP ON T1.CHL_ID = FP.FINPROD_ID
where
    T1.TOTLE_TRADE_ID = #{busiCode}
    AND T1.PORTFOLIO_ID IS NULL

/*根据cashId合并还本付息数据*/ select t8.cash_type, t8.CASH_ID, '${statusValid}' statusValid, '${CASH_TYPE_1_02}' CASH_TYPE_1_02, '${CASH_TYPE_2_C02}' CASH_TYPE_2_C02, t8.FINPROD_ID finprodId, t10.FINPROD_MARKET_ID,T8.SEC_ACCT_ID CHL_ID, t10.FINPROD_NAME,
/* 剩余本金 */ ROUND(SUM(T8.QTY), 4) qty,
0 intAdjustment, /* 借款利率 */ MAX(NVL(fccr.YIELD, 0))*100 yield, /*计息开始日 */ to_char(min(t8.VDATE), 'yyyy-MM-dd') vDate, /*计息结束日 */ to_char(t8.MDATE, 'yyyy-MM-dd') mDate, /*理论支付日 */ to_char(t8.PAY_DATE, 'yyyy-MM-dd') interestPayDay, /*还本金额 */ round(sum(nvl(t8.prinAmt, 0)), 4) returnAmount, /*理论本息总额*/ round(sum(nvl(t8.fpriceAmt, 0)), 4) theoryAmt, /*实收本息总额*/ round(sum(nvl(t8.prinAmt, 0) + T8.intAmt), 4) fpriceAmt, /*理论应收利息*/ round(sum(nvl(T8.intAmt, 0)), 4) intAmtTheory, round(sum(nvl(t8.prinAmt, 0) + T8.intAmt), 4) arrivalAmt, CASE WHEN T8.SEC_ACCT_ID= '999999' THEN 0 ELSE 1 END channel, FP.COLLECT_TYPE from (select T7.FINPROD_ID, T7.AMOUNT QTY, SUM(decode(T7.dqprinamt, null,cast (t7.int_prin_amt as DECIMAL(30,8)) * T7.AMOUNT/T7.MAX_CASH_BASEAMT, null)) return_amt, T7.PORTFOLIO_ID,T7.SEC_ACCT_ID, /*这一层，同一组合持仓对不用计划，数量不合并*/ listagg(T7.CASH_ID, ',') within GROUP ( ORDER BY T7.CASH_ID) CASH_ID, listagg(T7.CASH_TYPE, ',') within GROUP ( ORDER BY T7.CASH_ID) CASH_TYPE, MIN(T7.VDATE) VDATE, T7.MDATE, SUM(cast(T7.CASH_AMT as decimal(30,8))* T7.AMOUNT/T7.CASH_BASEAMT) fpriceAmt, MAX(T7.INT_PRIN_AMT) INT_PRIN_AMT, /*理论本息总额*/ SUM( cast(T7.PRIN_AMT as decimal(30,8)) * T7.AMOUNT/T7.CASH_BASEAMT) prinAmt /*还本金额*/, SUM(T7.INT_AMT/* - t7.payedInt*/) intAmt /*理论利息*/, T7.PAY_DATE from (SELECT T1.FINPROD_ID, T1.PORTFOLIO_ID,T1.SEC_ACCT_ID, T1.AMOUNT AMOUNT, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, t6.INT_PRIN_AMT, T6.PRIN_AMT, case when t6.cash_type in ('04', '01') then 0 else t6.prin_amt end dqprinamt, PSV.TDY_INTINCEXP, T6.CASH_BASEAMT, case when t6.cash_type IN (#{CASH_CLASS_TYPE01}, #{CASH_CLASS_TYPE04}) then NVL(PSV.TDY_INTINCEXP, t6.INT_AMT*T1.AMOUNT/T6.CASH_BASEAMT) WHEN T6.CASH_TYPE IN (#{CASH_CLASS_TYPE02}, #{CASH_CLASS_TYPE03}) AND T6.INT_AMT is not null and T6.INT_AMT != 0 AND PSV.SHARE_AMT is not null THEN ROUND(T6.PRIN_AMT * T1.AMOUNT/T6.CASH_BASEAMT * PSV.TDY_INTINCEXP/PSV.SHARE_AMT, 2) else t6.INT_AMT * T1.AMOUNT/t6.CASH_BASEAMT end INT_AMT, t6.PAY_DATE, MAX(FCP11.CASH_BASEAMT) MAX_CASH_BASEAMT from PTL_SEC_POSITION T1 INNER JOIN (select * from FIN_CASH_PLAN T2 WHERE T2.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T2.FINPROD_ID = #{finprodId} AND T2.MDATE = to_date(#{mDate}, 'yyyy-MM-dd') and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04}) and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0)
) T6 ON T1.FINPROD_ID = T6.FINPROD_ID AND T1.HODING_TYPE = #{POSITION_TYPE03} AND t1.CDATE < t6.MDATE and T1.AMOUNT > 0
AND T1.SEC_ACCT_ID = #{chlId}
LEFT JOIN PTL_SEC_VALUTION PSV ON T6.MDATE = PSV.CDATE + 1 day AND T1.PORTFOLIO_ID = PSV.PORTFOLIO_ID AND T1.FINPROD_ID = PSV.FINPROD_ID AND PSV.INV_AIM = '999999' INNER JOIN FIN_CASH_PLAN FCP11 ON T6.FINPROD_ID = FCP11.FINPROD_ID inner join PTL_PORTFOLIO pp on T1.PORTFOLIO_ID = pp.PORTFOLIO_ID where NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.IS_CANCEL = #{YESNO_N} and T6.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
/*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.IS_CANCEL = #{YESNO_N} and T6.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION tpsp where tpsp.HODING_TYPE = #{POSITION_TYPE03} and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID and tpsp.FINPROD_ID = T1.FINPROD_ID and tpsp.CDATE > T1.CDATE and tpsp.CDATE < T6.MDATE ) and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
and T1.PORTFOLIO_ID group by T1.FINPROD_ID, T1.PORTFOLIO_ID,T1.SEC_ACCT_ID, T1.AMOUNT, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, t6.INT_PRIN_AMT, T6.PRIN_AMT, PSV.TDY_INTINCEXP, T6.CASH_BASEAMT,PSV.TDY_INTINCEXP, t6.INT_AMT,PSV.SHARE_AMT, t6.PAY_DATE ) T7 GROUP BY T7.FINPROD_ID, T7.AMOUNT, T7.MDATE, T7.PORTFOLIO_ID,T7.SEC_ACCT_ID, T7.PAY_DATE ) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE fccr ON instr(t8.CASH_ID, fccr.CASH_ID) > 0 AND fccr.EFF_DATE <= t8.MDATE
LEFT JOIN FIN_PRODUCT_ADD FP ON T8.SEC_ACCT_ID = FP.FINPROD_ID WHERE NOT EXISTS(SELECT 1 FROM FIN_CASH_CALC_RULE T6 WHERE fccr.CASH_ID = T6.CASH_ID AND T6.EFF_DATE <= T8.MDATE AND T6.EFF_DATE > fccr.EFF_DATE ) and T10.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T10.FINPROD_ID = #{finprodId} group by t8.FINPROD_ID, t10.FINPROD_MARKET_ID,T8.SEC_ACCT_ID, t10.FINPROD_NAME, /*计息结束日 */ t8.MDATE, /*理论支付日 */ t8.PAY_DATE, t8.cash_type, t8.CASH_ID, FP.COLLECT_TYPE
